CREATE OR REPLACE FUNCTION erp.ensure_fg_accessory_cost_snapshot(p_lot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE l erp.fg_lots%ROWTYPE;p erp.production_orders%ROWTYPE;v_bom uuid;r record;v_category_avg numeric(18,6);v_hpp_factor numeric(18,6);v_reimburse_factor numeric(18,6);v_hpp_base numeric(18,6);v_reimburse_base numeric(18,6);v_snapshot uuid;v_commit_at timestamptz; BEGIN PERFORM erp.require_internal();SELECT * INTO l FROM erp.fg_lots WHERE id=p_lot_id FOR UPDATE; IF l.id IS NULL OR l.lot_origin<>'PRODUCTION' THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM erp.fg_accessory_cost_snapshots WHERE lot_id=l.id) THEN RETURN; END IF;SELECT * INTO p FROM erp.production_orders WHERE id=l.po_id; IF p.id IS NULL THEN RETURN; END IF;v_bom:=erp.commit_accessory_bom_for_lot(l.id); IF v_bom IS NULL THEN RETURN; END IF;SELECT committed_at INTO v_commit_at FROM erp.po_accessory_bom_commitments WHERE po_id=l.po_id AND product_id=l.product_id; FOR r IN SELECT abi.*,ac.base_uom_code FROM erp.accessory_bom_items abi JOIN erp.accessory_categories ac ON ac.id=abi.category_id WHERE abi.bom_version_id=v_bom ORDER BY ac.category_code LOOP v_category_avg:=erp.accessory_category_weighted_avg_cost_at(r.category_id,l.produced_at); IF r.hpp_method='CATEGORY_MOVING_AVG' THEN IF v_category_avg IS NULL THEN RAISE EXCEPTION 'Cannot snapshot HPP: accessory category % has no moving-average valuation history at %',r.category_id,l.produced_at; END IF;v_hpp_base:=v_category_avg; ELSE v_hpp_factor:=erp.accessory_uom_factor(r.category_id,r.hpp_uom_code,l.produced_at);v_hpp_base:=r.hpp_standard_rate/v_hpp_factor; END IF;v_reimburse_factor:=erp.accessory_uom_factor(r.category_id,r.reimbursement_uom_code,l.produced_at);v_reimburse_base:=r.reimbursement_rate/v_reimburse_factor; INSERT INTO erp.fg_accessory_cost_snapshots(lot_id,po_id,product_id,bom_version_id,bom_item_id,category_id,good_qty_pcs,qty_per_good_fg_base,hpp_method,category_avg_cost_base_snapshot,hpp_unit_cost_base_snapshot,reimbursement_unit_rate_base_snapshot,costing_basis_at,costing_basis_source) VALUES (l.id,l.po_id,l.product_id,v_bom,r.id,r.category_id,l.initial_qty_pcs,r.qty_per_good_fg_base,r.hpp_method,v_category_avg,v_hpp_base,v_reimburse_base,l.produced_at,CASE WHEN v_commit_at=l.produced_at THEN 'FIRST_FINANCIAL_USE' ELSE 'FG_ACCEPTANCE' END) RETURNING id INTO v_snapshot; IF p.contractor_id IS NULL AND v_reimburse_base>0 THEN RAISE EXCEPTION 'PO % has accessory reimbursement BOM but no mandor/contractor',p.po_number; END IF; IF p.contractor_id IS NOT NULL AND v_reimburse_base>0 THEN INSERT INTO erp.contractor_accessory_reimbursement_entitlements(snapshot_id,contractor_id,po_id,lot_id,product_id,category_id,physical_at,amount) SELECT v_snapshot,p.contractor_id,l.po_id,l.id,l.product_id,r.category_id,l.produced_at,total_reimbursement FROM erp.fg_accessory_cost_snapshots WHERE id=v_snapshot; END IF; END LOOP;END; $function$;

alter function "erp"."ensure_fg_accessory_cost_snapshot"(p_lot_id uuid) owner to "postgres";
